     1	// chapter-card — a bundled template (spec §11 G-44): a full card with a
     2	// large outlined chapter numeral, a kicker whose spacing settles, an accent
     3	// rule drawing across and the title revealed upward.
     4	export const meta = {
     5	  name: "Chapter card",
     6	  durationInFrames: 120,
     7	};
     8	
     9	export const schema = {
    10	  number:     { type: "number", default: 1, min: 0, max: 99, step: 1, animate: false },
    11	  kicker:     { type: "string", default: "CHAPTER" },
    12	  title:      { type: "string", default: "Getting started" },
    13	  background: { type: "color",  default: "#0b0b10" },
    14	  accent:     { type: "color",  default: "#ff5a36" },
    15	};
    16	
    17	export function render(frame, props, ctx) {
    18	  const u = Math.min(ctx.width, ctx.height) / 1080;
    19	  const D = ctx.durationInFrames;
    20	  const safeX = ctx.width * 0.05;
    21	  const safeW = ctx.width * 0.9;
    22	  const pad = 70 * u;
    23	  const left = safeX + pad;
    24	  const width = safeW - 2 * pad;
    25	  const numeral = String(Math.max(0, Math.min(99, Math.round(props.number)))).padStart(2, "0");
    26	  const numSize = 300 * u;
    27	  const numFont = { family: "Montserrat", size: numSize, weight: 900 };
    28	  const numW = measureText(numeral, numFont).width;
    29	  const titleSize = fitText(props.title, width, { family: "Montserrat", weight: 900 }, { min: 16 * u, max: 150 * u });
    30	  const kickerSize = 44 * u;
    31	  const blockH = numSize * 0.74 + 60 * u + titleSize * 0.74 + 40 * u;
    32	  const top = (ctx.height - blockH) / 2;
    33	  const numBase = top + numSize * 0.74;
    34	  const ruleY = numBase + 46 * u;
    35	  const titleBase = ruleY + 34 * u + titleSize * 0.74;
    36	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    37	  const lift = interpolate(frame, [D - 15, D - 1], [0, -24 * u], { easing: Easing.inCubic, clamp: true });
    38	  const numIn = interpolate(frame, [0, 22], [0, 1], { easing: Easing.outCubic, clamp: true });
    39	  const numScale = 1.15 - 0.15 * numIn;
    40	  const kickIn = interpolate(frame, [8, 30], [0, 1], { easing: Easing.outCubic, clamp: true });
    41	  const rule = interpolate(frame, [14, 38], [0, 1], { easing: Easing.inOutCubic, clamp: true });
    42	  const reveal = interpolate(frame, [22, 46], [0, 1], { easing: Easing.outCubic, clamp: true });
    43	  const kickerX = left + numW + 40 * u;
    44	  const kickerMax = left + width - kickerX;
    45	  // The kicker wraps beside the numeral, at most three lines at its widest spacing, shrinking (its
    46	  // spacing in proportion) until it does and until every word fits its room, so a line only ever
    47	  // breaks between words.
    48	  const kickerWords = props.kicker.split(/\s+/).filter((word) => word);
    49	  let kickerFit = kickerSize;
    50	  let kickerLines = [];
    51	  for (;;) {
    52	    const font = { family: "Montserrat", size: kickerFit, weight: 800, letterSpacing: (22 * u * kickerFit) / kickerSize };
    53	    kickerLines = kickerWords.length ? wrapText(props.kicker, kickerMax, font) : [];
    54	    const wordsFit = kickerWords.every((word) => measureText(word, font).width <= kickerMax);
    55	    if ((kickerLines.length <= 3 && wordsFit) || kickerFit <= 10 * u) break;
    56	    kickerFit = Math.max(10 * u, kickerFit * 0.9);
    57	  }
    58	  const spacing = ((22 - 14 * kickIn) * u * kickerFit) / kickerSize;
    59	  const kickerLead = kickerFit * 1.2;
    60	  const kickerTop = numBase - numSize * 0.37 + kickerFit * 0.36 - ((kickerLines.length - 1) * kickerLead) / 2;
    61	  const ncx = left + numW / 2;
    62	  const ncy = numBase - numSize * 0.37;
    63	  const ruleW = width * rule;
    64	  const rise = (1 - reveal) * titleSize * 1.15;
    65	  return svg(ctx, `
    66	    <defs>
    67	      <clipPath id="title"><rect x="${safeX}" y="${ruleY + 10 * u}" width="${safeW}" height="${titleBase - ruleY - 10 * u + titleSize * 0.26}"/></clipPath>
    68	    </defs>
    69	    <g transform="translate(0 ${lift})">
    70	      <g transform="translate(${ncx} ${ncy}) scale(${numScale}) translate(${-ncx} ${-ncy})">
    71	        <text x="${left}" y="${numBase}" font-family="Montserrat" font-weight="900" font-size="${numSize}" fill="none"
    72	              stroke="${props.accent}" stroke-width="${4 * u}" stroke-opacity="${numIn * out}">${numeral}</text>
    73	      </g>
    74	      <text x="${kickerX}" y="${kickerTop}" font-family="Montserrat" font-weight="800"
    75	            font-size="${kickerFit}" letter-spacing="${spacing}" fill="#d8d8e0"
    76	            fill-opacity="${kickIn * out}">${kickerLines.map((line, i) =>
    77	              `<tspan x="${kickerX}" y="${kickerTop + i * kickerLead}">${escapeXml(line)}</tspan>`).join("")}</text>
    78	      ${ruleW > 0.5 ? `<rect x="${left}" y="${ruleY}" width="${ruleW}" height="${6 * u}" fill="${props.accent}"
    79	            fill-opacity="${out}"/>` : ""}
    80	      <g clip-path="url(#title)">
    81	        <text x="${left}" y="${titleBase + rise}" font-family="Montserrat" font-weight="900" font-size="${titleSize}"
    82	              fill="#ffffff" fill-opacity="${out}">${escapeXml(props.title)}</text>
    83	      </g>
    84	    </g>`, { background: props.background });
    85	}

